  "assessment": "Confirmed active exfiltration from critical host web-01 to c2-01. Immediate containment of the exfiltration channel is required to minimize data loss while preserving forensic evidence and management access.",
  "evidence_review": [
    {
      "evidence_id": "M1",
      "decision": "contain",
      "reason": "Evidence M1 confirms unauthorized sensitive data exfiltration from web-01 to c2-01. This is a confirmed threat requiring immediate containment to stop data loss."
