  "actions": [
    {
      "kind": "block_egress",
      "target_id": "c2-01",
      "scope_host_ids": [
        "web-01"
      ],
      "evidence_ids": [
        "M1"
      ],
      "reason": "Blocks the confirmed exfiltration path from the critical host web-01 to the C2 destination c2-01. This minimizes data loss without isolating the critical host entirely, preserving management and evidence collection channels.",
