      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Availability impact on web-01 services is unknown as dependency details are not provided, though targeted egress blocking is less disruptive than full isolation.",
    "Forensic evidence preservation is maintained by preserving the evidence_collector channel, but the specific integrity of all logs depends on their storage location relative to the blocked egress."
  ],
