{
  "incident_id": "mitre-T1021-002",
  "telemetry_version": 1,
  "assessment": "Confirmed lateral movement and file spreading from workstation-01 via SMB. No evidence of exfiltration to external C2 or critical host compromise yet. Critical host web-01 is not directly linked to the threat source in evidence.",
  "evidence_review": [
    {
      "evidence_id": "M1",
      "decision": "contain",
      "reason": "Evidence M1 confirms active lateral movement and malicious file spreading from workstation-01. This requires immediate containment to stop the spread. Isolation is the most effective way to stop SMB-based lateral movement, but policy prohibits isolating critical hosts. workstation-01 is not critical, so isolation is permitted. However, restrict_lateral is a more targeted approach if it stops the specific SMB threat without full network cut, but given 'spreading to peer hosts', full isolation is safer to ensure containment. Wait, policy allows isolate_host for non-critical. Let's use isolate_host for workstation-01 to fully stop the spread. Actually, restrict_lateral might be sufficient if we only block SMB, but isolate_host is safer for 'spreading'. Let's stick to isolate_host for workstation-01 as it is non-critical and confirmed malicious."
    }
  ],
  "actions": [
    {
      "kind": "isolate_host",
      "target_id": "workstation-01",
      "scope_host_ids": [],
      "evidence_ids": [
        "M1"
      ],
      "reason": "Confirmed lateral movement and file spreading from workstation-01. Isolating this non-critical host stops the source of the threat. Management and evidence_collector channels are preserved for forensic collection.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Impact on dependent services for workstation-01 is unknown as dependency data is not provided.",
    "No evidence of exfiltration to c2-01 or other external destinations was found in the provided evidence, so no egress blocks are applied."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}

